<template>
	<section class="space-y-3">
		<p v-if="!docname" class="rounded-xl bg-ui-surface-yellow-50 p-3 text-sm text-ui-ink-yellow-800">Simpan pengajuan dulu, lalu foto bisa diunggah di sini.</p>
		<p v-else-if="canUpload" class="rounded-xl bg-ui-surface-yellow-50 p-3 text-sm text-ui-ink-yellow-800">Foto belum tersimpan sampai Anda menekan Save.</p>
		<p v-if="loading" class="text-sm text-ui-ink-gray-500">Memuat checklist foto…</p>
		<div v-if="error" role="alert" class="rounded-xl bg-ui-surface-red-50 p-3 text-sm text-ui-ink-red-700">
			<p class="whitespace-pre-wrap">{{ error }}</p>
			<button v-if="loadFailed" type="button" class="mt-2 underline" @click="loadChecklist">Coba lagi</button>
		</div>
		<p v-if="busy" role="status" class="text-sm text-primary">{{ busyMessage }}</p>
		<div
			v-if="groups.length"
			class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm"
		>
		<details
			v-for="group in groups"
			:key="group.name"
			class="group border-t border-ui-line-gray-200 first:border-t-0"
		>
			<summary class="flex cursor-pointer list-none items-start justify-between gap-3 px-4 py-3 [&::-webkit-details-marker]:hidden">
				<div class="min-w-0">
					<h3 class="text-base font-semibold text-ui-ink-gray-900">
						{{ group.name }}
					</h3>
					<p class="mt-1 text-xs font-medium text-ui-ink-gray-400">{{ progress(group.items) }}</p>
				</div>
				<svg viewBox="0 0 24 24" class="mt-1 h-5 w-5 shrink-0 text-ui-ink-gray-400 transition group-open:rotate-180" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
					<path d="m6 9 6 6 6-6" />
				</svg>
			</summary>

			<div class="grid grid-cols-1 gap-4 px-4 pb-4 md:grid-cols-2">
				<div
					v-for="item in group.items"
					:key="item.jenis_foto"
					class="rounded-2xl border border-ui-line-gray-200 bg-ui-surface p-4"
				>
					<div class="flex flex-wrap items-center justify-between gap-3">
						<p class="min-w-0 flex-1 text-base font-semibold text-ui-ink-gray-800">
							{{ item.nama_foto }}
						</p>
						<div v-if="canUpload && !item.archived" class="flex shrink-0 gap-2">
							<button
								type="button"
								class="inline-flex h-10 w-10 items-center justify-center rounded-full border border-primary text-primary transition hover:bg-primary/5 disabled:cursor-not-allowed disabled:opacity-50"
								:disabled="busy || full(item)"
								:title="item.terima_pdf ? 'Upload foto atau PDF' : 'Upload foto'"
								:aria-label="item.terima_pdf ? 'Upload foto atau PDF' : 'Upload foto'"
								@click="pick(item)"
							>
								<svg viewBox="0 0 24 24" class="h-4 w-4 shrink-0" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
									<circle cx="12" cy="12" r="10" />
									<path d="m16 12-4-4-4 4" />
									<path d="M12 16V8" />
								</svg>
							</button>
							<button
								type="button"
								class="inline-flex h-10 w-10 items-center justify-center rounded-full border border-primary text-primary transition hover:bg-primary/5 disabled:cursor-not-allowed disabled:opacity-50"
								:disabled="busy || full(item)"
								title="Ambil foto dengan kamera"
								aria-label="Ambil foto dengan kamera"
								@click="camera(item)"
							>
								<svg viewBox="0 0 24 24" class="h-4 w-4 shrink-0" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
									<path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3z" />
									<circle cx="12" cy="13" r="4" />
								</svg>
							</button>
						</div>
					</div>

					<p class="mt-2 text-xs text-ui-ink-gray-400">
						{{ item.wajib ? 'Wajib' : 'Opsional' }} · {{ item.terima_pdf ? 'JPG, PNG, atau PDF' : 'JPG atau PNG' }}<span v-if="item.maks_file > 0"> · maksimal {{ item.maks_file }} file</span>
					</p>
					<p v-if="item.instruksi" class="mt-1 whitespace-pre-wrap text-xs text-ui-ink-gray-500">
						{{ item.instruksi }}
					</p>

					<div v-if="rowsFor(item).length" class="mt-3 space-y-2">
						<div
							v-for="(row, index) in rowsFor(item)"
							:key="row.name || row.foto + index"
							class="flex items-center justify-between gap-2 rounded-lg border border-ui-line-gray-200 bg-ui-surface-gray-50 px-3 py-2"
						>
							<button type="button" class="min-w-0 truncate text-left text-sm font-medium text-primary hover:underline" @click="openFile(row.foto, item.nama_foto)">
								{{ item.nama_foto }} {{ index + 1 }}
							</button>
							<button
								v-if="canUpload"
								type="button"
								:disabled="busy"
								class="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-ui-ink-red-500 transition hover:bg-ui-surface-red-50 hover:text-ui-ink-red-600 disabled:opacity-50"
								:aria-label="`Hapus foto ${index + 1} ${item.nama_foto}`"
								@click="removeRow(row)"
							>
								<svg viewBox="0 0 24 24" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
									<path d="M3 6h18" />
									<path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
								</svg>
							</button>
						</div>
					</div>
				</div>
			</div>
		</details>
		</div>
		<p v-if="!loading && !loadFailed && !groups.length" class="text-sm text-ui-ink-gray-500">Belum ada item checklist foto.</p>
		<details v-if="legacyAttachments.length" class="rounded-2xl border border-ui-line-gray-200 bg-ui-surface p-4">
			<summary class="cursor-pointer text-sm font-semibold">Lampiran Sebelumnya</summary>
			<button v-for="(file, index) in legacyAttachments" :key="index" type="button" class="mt-3 block text-sm text-primary" @click="openAttachment(file.url, file.label)">{{ file.label }}</button>
		</details>
		<input ref="fileInput" type="file" :accept="ACCEPT" multiple class="hidden" @change="onFiles" />
		<Teleport to="body">
			<div v-if="cameraOpen" class="fixed inset-0 z-[80] flex items-center justify-center bg-black/80 p-4" role="dialog" aria-modal="true" aria-label="Ambil foto" @keydown.esc="closeCamera">
				<div class="w-full max-w-lg rounded-2xl bg-ui-surface p-4">
					<video ref="video" autoplay playsinline muted class="max-h-[65vh] w-full rounded-lg" />
					<div class="mt-3 flex justify-end gap-3">
						<button type="button" class="rounded-lg border px-4 py-2" @click="closeCamera">Batal</button>
						<button type="button" :disabled="!cameraReady" class="rounded-lg bg-primary px-4 py-2 text-ui-onPrimary disabled:opacity-50" @click="takePhoto">Ambil Foto</button>
					</div>
				</div>
			</div>
		</Teleport>
	</section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { capturePhoto } from '../composables/cameraCapture'
import { openImage } from '../composables/attachmentViewer'
import { kompresFoto } from '../composables/imageCompress'
import { isPdfUrl, openAttachment } from '../composables/pdfViewer'
import { isNativeApp } from '../data/mobile'

const props = defineProps({
	modelValue: { type: Array, default: () => [] },
	docname: { type: String, default: '' },
	kategori: { type: String, default: '' },
	status: { type: String, default: '' },
	editable: Boolean,
	maxAttachments: { type: Number, default: 0 },
	attachmentTotal: { type: Number, default: 0 },
	legacyAttachments: { type: Array, default: () => [] },
})
const emit = defineEmits(['update:modelValue', 'busy'])
const API = '/api/method/juragan.juragan.doctype.data_pengajuan.foto_pengajuan.'
// Cerminan ALLOWED_EXTENSIONS + PDF_KELOMPOK di foto_pengajuan.py — server tetap yang menegakkan.
const ACCEPT = 'image/jpeg,image/png'
const ACCEPT_PDF = `${ACCEPT},application/pdf,.pdf`
const items = ref([]), loading = ref(false), loadFailed = ref(false), error = ref('')
const serverCanUpload = ref(false), busy = ref(false), busyMessage = ref('')
const fileInput = ref(null), selected = ref(null)
const cameraOpen = ref(false), cameraReady = ref(false), video = ref(null)
let stream = null, requestId = 0, disposed = false
const canUpload = computed(() => !!props.docname && props.editable && serverCanUpload.value && !loading.value && !loadFailed.value)
watch(busy, value => emit('busy', value), { flush: 'sync' })
const rowsFor = item => props.modelValue.filter(row => row.jenis_foto === item.jenis_foto && row.foto)
const full = item => item.maks_file > 0 && rowsFor(item).length >= item.maks_file
const groups = computed(() => {
	const grouped = new Map(['Foto Survey dan Data Pengajuan', 'Foto Kendaraan dan Dokumen', 'Foto Pendukung Lain'].map(name => [name, []]))
	const all = [...items.value], known = new Set(all.map(item => item.jenis_foto))
	for (const row of props.modelValue) {
		if (!row.foto || known.has(row.jenis_foto)) continue
		known.add(row.jenis_foto)
		all.push({ jenis_foto: row.jenis_foto, nama_foto: row.label_foto || row.jenis_foto, kelompok: 'Foto Tersimpan Sebelumnya', archived: true })
	}
	for (const item of all) {
		const group = item.kelompok || 'Foto Pendukung Lain'
		if (!grouped.has(group)) grouped.set(group, [])
		grouped.get(group).push(item)
	}
	return [...grouped].filter(([, rows]) => rows.length).map(([name, rows]) => ({ name, items: rows }))
})
function progress(rows) {
	const required = rows.filter(item => item.wajib)
	return required.length ? `${required.filter(item => rowsFor(item).length).length} dari ${required.length} foto wajib sudah diunggah` : 'Foto opsional'
}
async function api(method, options = {}) {
	const response = await fetch(API + method, { credentials: 'include', ...options, headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '', ...options.headers } })
	const payload = await response.json().catch(() => ({}))
	if (!response.ok || payload.exc || payload.exception) {
		let message = payload.message || `Permintaan gagal (${response.status}).`
		try { message = JSON.parse(payload._server_messages).map(value => JSON.parse(value).message).join('\n') } catch { /* use fallback */ }
		const el = document.createElement('div'); el.innerHTML = String(message)
		throw new Error(el.textContent || 'Permintaan gagal.')
	}
	return payload.message
}
async function loadChecklist() {
	const id = ++requestId
	loading.value = true; error.value = ''; loadFailed.value = false; serverCanUpload.value = false
	try {
		const params = new URLSearchParams(props.docname ? { docname: props.docname } : { kategori: props.kategori })
		const result = await api('get_checklist?' + params)
		if (id !== requestId || disposed) return
		items.value = result.items || []; serverCanUpload.value = !!result.dapat_upload
	} catch (e) {
		if (id !== requestId || disposed) return
		error.value = e.message; loadFailed.value = true
	} finally { if (id === requestId) loading.value = false }
}
watch(() => [props.docname, props.kategori, props.status, props.editable], loadChecklist, { immediate: true })
function pick(item) {
	if (!canUpload.value || busy.value || full(item)) return
	// `accept` di-set langsung, bukan lewat binding: click() di bawah jalan sebelum
	// Vue sempat memperbarui atribut.
	selected.value = item; fileInput.value.accept = item.terima_pdf ? ACCEPT_PDF : ACCEPT
	fileInput.value.value = ''; fileInput.value.click()
}
async function onFiles(event) {
	const files = Array.from(event.target.files || []); event.target.value = ''
	await uploadFiles(selected.value, files)
}
async function uploadFiles(item, files) {
	if (!item || !files.length || !canUpload.value || busy.value) return
	error.value = ''
	if (item.maks_file > 0 && rowsFor(item).length + files.length > item.maks_file) {
		error.value = `Maksimal ${item.maks_file} file untuk ${item.nama_foto}.`; return
	}
	if (props.maxAttachments && props.attachmentTotal + files.length > props.maxAttachments) {
		error.value = `Maksimal ${props.maxAttachments} lampiran per pengajuan. Hapus lampiran lain dulu.`; return
	}
	busy.value = true
	const docname = props.docname
	let rows = [...props.modelValue]
	try {
		// Perkecil di perangkat dulu: yang dikirim ratusan KB, bukan foto kamera 3–12 MB.
		// Validasi dilakukan pada hasilnya, jadi foto kamera >12 MB pun tetap bisa masuk.
		busyMessage.value = files.length > 1 ? `Menyiapkan ${files.length} foto…` : 'Menyiapkan foto…'
		const prepared = []
		// PDF dikirim apa adanya; hanya foto yang diperkecil.
		for (const file of files) prepared.push(isPdfUrl(file.name) ? file : await kompresFoto(file))
		const format = item.terima_pdf ? /\.(jpe?g|png|pdf)$/i : /\.(jpe?g|png)$/i
		for (const file of prepared) {
			if (!format.test(file.name)) { error.value = item.terima_pdf ? 'Format file harus JPG, PNG, atau PDF.' : 'Format foto harus JPG atau PNG.'; return }
			if (file.size > 12 * 1024 * 1024) { error.value = 'Ukuran file maksimal 12 MB.'; return }
		}
		for (const [index, file] of prepared.entries()) {
			if (disposed || props.docname !== docname) break
			busyMessage.value = `Mengunggah ${index + 1} dari ${files.length} foto…`
			const data = new FormData(); data.append('file', file, file.name); data.append('jenis_foto', item.jenis_foto); data.append('docname', docname)
			const uploaded = await api('upload_foto', { method: 'POST', body: data })
			if (disposed || props.docname !== docname) break
			rows = [...rows, { doctype: 'Foto Pengajuan', jenis_foto: uploaded.jenis_foto, label_foto: uploaded.label_foto, urutan: uploaded.urutan, foto: uploaded.file_url }]
			emit('update:modelValue', rows)
		}
	} catch (e) { error.value = e.message }
	finally { busy.value = false }
}
function openFile(url, title) {
	// PDF → viewer in-app (pdfViewer); foto tetap lightbox seperti sebelumnya.
	if (isPdfUrl(url)) openAttachment(url, title)
	else openImage(url, title)
}
function removeRow(row) {
	if (!canUpload.value || busy.value) return
	emit('update:modelValue', props.modelValue.filter(value => value !== row))
}
async function camera(item) {
	if (!canUpload.value || busy.value || full(item)) return
	selected.value = item; error.value = ''
	if (isNativeApp()) {
		let file = await capturePhoto()
		if (file && !/\.(jpe?g|png)$/i.test(file.name || '')) {
			file = new File([file], `kamera_${Date.now()}.jpg`, {
				type: file.type || 'image/jpeg',
			})
		}
		if (file) await uploadFiles(item, [file])
		return
	}
	try {
		if (!navigator.mediaDevices?.getUserMedia) throw new Error('Kamera memerlukan browser yang mendukung dan koneksi HTTPS. Gunakan tombol unggah untuk memilih foto.')
		cameraOpen.value = true; await nextTick()
		const media = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false })
		if (!cameraOpen.value || disposed) { media.getTracks().forEach(track => track.stop()); return }
		stream = media; video.value.srcObject = media; await video.value.play(); cameraReady.value = true
	} catch (e) { closeCamera(); error.value = `Kamera tidak dapat dibuka: ${e.message}` }
}
function closeCamera() {
	cameraOpen.value = false; cameraReady.value = false
	stream?.getTracks().forEach(track => track.stop()); stream = null
}
async function takePhoto() {
	const canvas = document.createElement('canvas')
	canvas.width = video.value.videoWidth; canvas.height = video.value.videoHeight
	if (!canvas.width || !canvas.height) return
	canvas.getContext('2d').drawImage(video.value, 0, 0)
	const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', 0.9))
	closeCamera()
	if (blob) await uploadFiles(selected.value, [new File([blob], `kamera_${Date.now()}.jpg`, { type: 'image/jpeg' })])
}
onBeforeUnmount(() => { disposed = true; ++requestId; closeCamera(); emit('busy', false) })
</script>
